import { expect, test, uniqueName, sample } from "../../fixtures";

function isoDateFromToday(days: number): string {
  const d = new Date();
  d.setDate(d.getDate() + days);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function insuranceCertificate(expiry: string): string {
  return [
    "Insurer: Harbor Mutual",
    "Policy Number: HM-55-1290",
    "Coverage Amount: $2,000,000",
    `Expiry Date: ${expiry}`,
    "",
  ].join("\n");
}

const W9 = "Legal Name: Acme Freight LLC\nTax ID: 12-3456789\nBusiness Type: LLC\n";
const CONTRACT = "Counterparty: Acme Freight LLC\nEffective Date: 2026-01-01\nExpiry Date: 2027-12-31\n";

const rows: Array<{ days: number; include: boolean }> = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
];

for (const { days, include } of rows) {
  test(
    `insurance expiring in ${days} days ${include ? "is" : "is not"} flagged insurance_expiring_soon`,
    { tag: "@REV-08" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const created = await member.post("/api/vendors", {
        data: {
          name: uniqueName("Expiry Vendor"),
          category: "logistics",
          contact_email: "ops@acme.example",
        },
      });
      expect(created.status(), await created.text()).toBe(201);
      const vendor = await created.json();

      const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "insurance_certificate",
          file: {
            name: "insurance.txt",
            mimeType: "text/plain",
            buffer: Buffer.from(insuranceCertificate(isoDateFromToday(days))),
          },
        },
      });
      expect(upload.status(), await upload.text()).toBe(201);
      const document = await upload.json();

      // Wait for background extraction to finish before reading flags.
      await expect
        .poll(
          async () => {
            const res = await member.get(`/api/documents/${document.id}`);
            expect(res.status(), await res.text()).toBe(200);
            return (await res.json()).status;
          },
          { timeout: 15_000 },
        )
        .toBe("extracted");

      // Act
      const response = await member.get(`/api/vendors/${vendor.id}`);

      // Assert
      expect(response.status(), await response.text()).toBe(200);
      const body = await response.json();
      if (include) {
        expect(body.flags, JSON.stringify(body)).toContain("insurance_expiring_soon");
      } else {
        expect(body.flags, JSON.stringify(body)).not.toContain("insurance_expiring_soon");
      }
    },
  );
}
